begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','admin_hide_flight',array['uuid','text'],'Guarded moderation exists');
select has_function('public','admin_flight_overview',array['uuid'],'Guarded overview exists');
select has_column('public','flights','moderated_at','Retained hidden state exists');
insert into auth.users(id,email) select ('21500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'moderation-'||n||'@example.invalid' from generate_series(1,6) n;
insert into public.memberships(user_id,role) select ('21500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'admin' else 'member' end::public.member_role from generate_series(1,5) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('21500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Moderation pilot','KPAO','licensed' from generate_series(2,3) n;
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility,notes)
select ('21510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'21500000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','C172',2,case when n=1 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility,'Retained post note' from generate_series(1,4) n;
insert into public.flight_recipients(flight_id,user_id) select '21510000-0000-4000-8000-000000000001',('21500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(2,3) n;
insert into public.flight_requests(id,flight_id,requester_id,introductory_note) select ('21520000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'21510000-0000-4000-8000-000000000001',('21500000-0000-4000-8000-'||lpad((n+1)::text,12,'0'))::uuid,'Retained request note' from generate_series(1,2) n;
update public.flight_requests set status='accepted' where id='21520000-0000-4000-8000-000000000001';
insert into public.conversations(id,flight_request_id,owner_id,requester_id) values('21530000-0000-4000-8000-000000000001','21520000-0000-4000-8000-000000000001','21500000-0000-4000-8000-000000000001','21500000-0000-4000-8000-000000000002');
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('21500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.hide(n integer default 1,reason text default 'Safety review') returns jsonb language sql as $$select public.admin_hide_flight(('21510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,reason);$$;
select ok((select relrowsecurity from pg_class where oid='public.flight_moderation_audit'::regclass),'Audit RLS enabled');
select ok(not has_function_privilege('anon','public.admin_hide_flight(uuid,text)','EXECUTE'),'Anonymous execute denied');
select ok(not has_function_privilege('service_role','public.admin_hide_flight(uuid,text)','EXECUTE'),'Service RPC bypass denied');
set local role authenticated;
select pg_temp.actor(1);
select throws_ok($$select pg_temp.hide()$$,'42501',null,'Owner cannot spoof admin');
select throws_ok($$select public.admin_flight_overview(null)$$,'42501',null,'Member overview denied');
select throws_ok($$update public.flights set moderated_at=now()$$,'42501',null,'Direct hidden write denied');
select is((select count(*)::integer from public.flight_moderation_audit),0,'Member cannot read audit');
select pg_temp.actor(6);
select throws_ok($$select pg_temp.hide()$$,'42501',null,'Unadmitted identity denied');
select pg_temp.actor(2);
select public.send_conversation_message('21530000-0000-4000-8000-000000000001','21540000-0000-4000-8000-000000000001','Private retained message');
select pg_temp.actor(4);
select is((select count(*)::integer from public.flights where id='21510000-0000-4000-8000-000000000001'),0,'Ordinary admin cannot read unselected PRIVATE post');
select ok(exists(select 1 from jsonb_array_elements(public.admin_flight_overview(null)) r where r->>'id'='21510000-0000-4000-8000-000000000001' and r->>'notes'='Retained post note'),'Guarded admin overview may inspect PRIVATE post');
select ok(public.admin_flight_overview(null)::text not like '%Private retained message%','Overview excludes conversation contents');
select is((select count(*)::integer from public.messages where id='21540000-0000-4000-8000-000000000001'),0,'Unrelated admin cannot read messages');
select throws_ok($$select pg_temp.hide(reason=>' ')$$,'22023',null,'Blank reason rejected');
select throws_ok($$select pg_temp.hide(reason=>repeat('x',501))$$,'22023',null,'Oversized reason rejected');
select is(pg_temp.hide(99)->>'code','flight_unavailable','Unknown target has fixed outcome');
reset role;
create function pg_temp.reject_moderation() returns trigger language plpgsql as $$begin raise exception 'Owned audit failure'; end;$$;
create trigger test_reject_moderation before insert on public.flight_moderation_audit for each row execute function pg_temp.reject_moderation();
set local role authenticated;
select throws_ok($$select pg_temp.hide()$$,'P0001',null,'Audit failure rejects moderation');
reset role;
select is((select status::text from public.flights where id='21510000-0000-4000-8000-000000000001'),'open','Audit failure rolls back flight');
select is((select count(*)::integer from public.flight_requests where flight_id='21510000-0000-4000-8000-000000000001' and status in ('pending','accepted')),2,'Audit failure rolls back request closure');
select ok((select closed_at is null from public.conversations where id='21530000-0000-4000-8000-000000000001'),'Audit failure rolls back conversation closure');
drop trigger test_reject_moderation on public.flight_moderation_audit;
set local role authenticated;
select is(pg_temp.hide()->>'code','hidden','Active admin hides flight');
select is(pg_temp.hide(reason=>'Different retry')->>'code','already_hidden','Retry confirms original hide');
select is((select count(*)::integer from public.flight_moderation_audit),1,'Retry produces one immutable event');
select throws_ok($$update public.flight_moderation_audit set reason='rewrite'$$,'42501',null,'Audit update denied');
select throws_ok($$delete from public.flight_moderation_audit$$,'42501',null,'Audit delete denied');
select throws_ok($$insert into public.flight_moderation_audit(actor_id,flight_id,created_at,reason) values('21500000-0000-4000-8000-000000000004','21510000-0000-4000-8000-000000000002',now(),'forged')$$,'42501',null,'Direct audit insert denied');
reset role;
select ok(exists(select 1 from public.flight_moderation_audit a join public.flights f on f.id=a.flight_id where a.actor_id='21500000-0000-4000-8000-000000000004' and a.reason='Safety review' and a.action='flight_hidden' and a.created_at=f.moderated_at and f.status='cancelled'),'Actor target time reason and closed state bind atomically');
select is((select count(*)::integer from public.flight_requests where flight_id='21510000-0000-4000-8000-000000000001' and status='cancelled'),2,'Both active request states cancelled');
select ok((select closed_at is not null from public.conversations where id='21530000-0000-4000-8000-000000000001'),'Conversation closed atomically');
select is((select count(*)::integer from public.flight_recipients where flight_id='21510000-0000-4000-8000-000000000001'),2,'PRIVATE selection history retained');
select throws_ok($$update public.flights set status='open' where id='21510000-0000-4000-8000-000000000001'$$,'23514',null,'Hidden flight cannot be reopened');
set local role authenticated;
select pg_temp.actor(2);
select is((select count(*)::integer from public.flights where id='21510000-0000-4000-8000-000000000001'),0,'Selected requester cannot read hidden post');
select is((select status::text from public.flight_requests where id='21520000-0000-4000-8000-000000000001'),'cancelled','Requester retains closed request history');
select is((select count(*)::integer from public.messages where conversation_id='21530000-0000-4000-8000-000000000001'),1,'Participant retains private message history');
select throws_ok($$select public.send_conversation_message('21530000-0000-4000-8000-000000000001',gen_random_uuid(),'After hide')$$,'42501',null,'Hidden connection cannot send');
select is(public.get_flight_connection('21520000-0000-4000-8000-000000000001'),null::jsonb,'Hidden connection is inactive');
select is(public.submit_flight_interest('21510000-0000-4000-8000-000000000001')->>'code','flight_unavailable','Hidden flight rejects interest');
select pg_temp.actor(1);
select is((select notes from public.flights where id='21510000-0000-4000-8000-000000000001'),'Retained post note','Owner retains post record');
select is(public.decide_flight_request('21510000-0000-4000-8000-000000000001','21520000-0000-4000-8000-000000000002','accepted')->>'code','request_conflict','Cannot accept after moderation');
reset role;
update public.flights set status='completed' where id='21510000-0000-4000-8000-000000000002';
update public.flights set status='cancelled' where id='21510000-0000-4000-8000-000000000003';
set local role authenticated;
select pg_temp.actor(4);
select is(pg_temp.hide(2)->>'status','completed','Completed lifecycle preserved when hiding');
select is(pg_temp.hide(3)->>'status','cancelled','Cancelled lifecycle preserved when hiding');
select is(jsonb_array_length(public.admin_flight_overview('ffffffff-ffff-ffff-ffff-ffffffffffff')),0,'Overview cursor bounded');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned fixture' where user_id='21500000-0000-4000-8000-000000000004';
set local role authenticated;
select throws_ok($$select pg_temp.hide(4)$$,'42501',null,'Retained disabled admin session denied');
select throws_ok($$select public.admin_flight_overview(null)$$,'42501',null,'Disabled admin overview denied');
select is((select count(*)::integer from public.flight_moderation_audit),0,'Disabled admin audit reads revoked');
reset role;
select * from finish();
rollback;
